'use strict';
const api='../api/index.php';const $=id=>document.getElementById(id);let stream=null;
function show(id){['homePanel','scanPanel','walkinPanel','ticketPanel'].forEach(x=>$(x).classList.toggle('hidden',x!==id));if(id!=='scanPanel')stopCamera()}
document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>show(b.dataset.open));document.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>show('homePanel'));$('finishButton').onclick=()=>show('homePanel');$('printButton').onclick=()=>window.print();
function tokenFrom(value){const raw=value.trim();try{const url=new URL(raw);return url.searchParams.get('t')||url.pathname.split('/').filter(Boolean).pop()||raw}catch{return raw}}
async function request(action,payload){const response=await fetch(`${api}?action=${action}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const body=await response.json();if(!response.ok)throw new Error(body.error||'ไม่สามารถดำเนินการได้');return body}
$('scanForm').onsubmit=async e=>{e.preventDefault();const token=tokenFrom($('scanToken').value);const mode=e.submitter?.value||'status';$('scanError').classList.add('hidden');if(mode==='status'){location.href=`status.html?t=${encodeURIComponent(token)}`;return}try{const body=await request('kiosk-check-in',{token});renderTicket(body.ticket.public_id,body.ticket.queue_no,body.ticket.estimated_wait_minutes)}catch(error){$('scanError').textContent=error.message;$('scanError').classList.remove('hidden')}};
async function loadSlots(){const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());try{const response=await fetch(`${api}?action=public-slots&date=${today}`,{cache:'no-store'});const body=await response.json();if(!response.ok)throw new Error(body.error);$('slotSelect').innerHTML=body.data.map(x=>`<option value="${x.id}">${x.start_time}–${x.end_time} น. · ${x.department_name} · ${x.service_name}</option>`).join('')||'<option value="">ไม่มีบริการที่เปิดรับในขณะนี้</option>'}catch(error){$('walkinError').textContent=error.message;$('walkinError').classList.remove('hidden')}}
$('walkinForm').onsubmit=async e=>{e.preventDefault();$('walkinError').classList.add('hidden');try{const body=await request('kiosk-walk-in',{slot_id:+$('slotSelect').value,customer_name:$('walkinName').value,customer_phone:$('walkinPhone').value});renderTicket(body.ticket.public_id,body.ticket.queue_no,body.ticket.estimated_wait_minutes)}catch(error){$('walkinError').textContent=error.message;$('walkinError').classList.remove('hidden')}};
function renderTicket(token,no,wait){$('ticketNo').textContent=no;$('ticketWait').textContent=wait>0?`เวลารอประมาณ ${wait} นาที`:'ใกล้ถึงคิวของคุณแล้ว';const url=new URL('status.html',location.href);url.searchParams.set('t',token);$('statusLink').href=url.href;$('ticketToken').textContent=token;const qr=qrcode(0,'M');qr.addData(url.href);qr.make();$('ticketQr').src=qr.createDataURL(7,10);show('ticketPanel')}
async function stopCamera(){if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}$('video').classList.add('hidden');$('cameraButton').classList.remove('hidden')}
$('cameraButton').onclick=async()=>{if(!('BarcodeDetector'in window)){ $('scanError').textContent='อุปกรณ์นี้ยังไม่รองรับกล้องสแกนอัตโนมัติ กรุณาใช้เครื่องสแกนหรือกรอกรหัส';$('scanError').classList.remove('hidden');return}try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});$('video').srcObject=stream;await $('video').play();$('video').classList.remove('hidden');$('cameraButton').classList.add('hidden');const detector=new BarcodeDetector({formats:['qr_code']});const scan=async()=>{if(!stream)return;const codes=await detector.detect($('video')).catch(()=>[]);if(codes[0]){$('scanToken').value=tokenFrom(codes[0].rawValue);stopCamera();$('scanToken').focus();return}requestAnimationFrame(scan)};scan()}catch(error){$('scanError').textContent='ไม่สามารถเปิดกล้องได้ กรุณาอนุญาตการใช้กล้องหรือกรอกรหัสแทน';$('scanError').classList.remove('hidden')}};
loadSlots();
